insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c8423c9a-44a2-40be-8f74-4316fae629e4', 'N4', 'Vる／Nの＋予定です', 'Có kế hoạch làm gì ~', '予定 = kế hoạch, thường do 1 tổ chức (trường/công ty) hoặc nhiều người quyết định', 'V(thể từ điển)／N + の + 予定です', 'Thông báo kế hoạch đã định trước (thường do tổ chức/nhiều người quyết định)', NULL, NULL, NULL, '{}', NULL, 40, 'Vる／Nの＋予定です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c4947afa-27a3-4969-9c15-b5d8b5c4ee7f', 'N4', 'Vた／Vない＋ほうがいいです', 'Nên/ Không nên làm gì', 'ほうがいい = nên; thể た cho khẳng định, thể ない cho phủ định', 'V(thể た)／V(thể ない) + ほうがいいです', 'Đưa ra lời khuyên nên hoặc không nên làm gì', NULL, NULL, NULL, '{}', NULL, 40, 'Vた／Vない＋ほうがいいです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('4eb8d331-dca6-488c-b573-7574fc26ebec', 'N4', 'Vる/ない、Aな/Nじゃない、Aい/Aくない ＋ でしょう', 'Có lẽ/ hẳn là/ chắc là ~ (dự đoán)', 'でしょう dùng để dự đoán với độ tự tin khá cao', 'Vる/ない・Aな/Nじゃない・Aい/Aくない + でしょう', 'Dự đoán 1 sự việc sẽ xảy ra', NULL, NULL, NULL, '{}', NULL, 40, 'Vる/ない、Aな/Nじゃない、Aい/Aくない ＋ でしょう', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('4d58ed1b-49a1-470f-9aa0-2c3f3906e99e', 'N4', 'Vる/Vない、Aな/N、Aい/Aくない ＋ かもしれません', 'Không khéo mà lại ~/khả năng là ~/có lẽ là ~', 'かもしれません độ tự tin thấp hơn でしょう', 'Vる/Vない・Aな/N・Aい/Aくない + かもしれません', 'Dự đoán với độ chắc chắn thấp, khả năng có thể xảy ra', NULL, NULL, NULL, '{}', NULL, 40, 'Vる/Vない、Aな/N、Aい/Aくない ＋ かもしれません', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ca85c642-3809-40a0-8f99-d5a31b061abc', 'N4', 'Vる＋な', 'Đừng làm gì ~ (thể cấm đoán)', 'Vる+な là thể cấm đoán mạnh, thường dùng trong khẩu ngữ nam giới/biển báo', 'V(thể từ điển) + な', 'Ra lệnh/cấm đoán ai đó không được làm gì (thể mạnh, thân mật)', NULL, NULL, NULL, '{}', NULL, 40, 'Vる＋な', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('1f83aafa-6b81-40ec-9053-91cec31ec163', 'N4', 'Vます＋なさい', 'Cách nói mệnh lệnh', 'V-ます (bỏ ます) + なさい, mệnh lệnh nhẹ nhàng hơn Vる+な', 'V(bỏ ます) + なさい', 'Ra lệnh nhẹ nhàng (thường người lớn nói với trẻ nhỏ)', NULL, NULL, NULL, '{}', NULL, 40, 'Vます＋なさい', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ad936b93-4969-47dc-bc57-0425dadfec8d', 'N4', 'XはYという意味です', 'X có nghĩa là Y', 'という意味です dùng để giải thích nghĩa của 1 từ/câu', 'X + は + Y + という意味です', 'Giải thích ý nghĩa của 1 từ hoặc câu nói', NULL, NULL, NULL, '{}', NULL, 40, 'XはYという意味です', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('294898ce-a57f-4600-b6ec-6d1f27afb3ee', 'N4', '～と言いました／～と言っていました', 'Ai đó đã nói rằng ~', '言っていました nhấn mạnh việc thuật lại lời nói của người khác', '[câu trích dẫn] + と言いました／と言っていました', 'Thuật lại lời của người khác đã nói', NULL, NULL, NULL, '{}', NULL, 40, '～と言いました／～と言っていました', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fbd18589-8f92-4ae2-a26c-7a23573e1e55', 'N4', '[Câu văn/thể thường] と伝えていただけませんか', 'Truyền đạt lại lời nhắn', '伝えていただけませんか = nhờ ai đó chuyển lời một cách lịch sự', '[câu trích dẫn thể thường] + と伝えていただけませんか', 'Nhờ ai đó truyền đạt lại 1 lời nhắn cho người thứ ba', NULL, NULL, NULL, '{}', NULL, 40, '[Câu văn/thể thường] と伝えていただけませんか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e99239c7-348f-4743-9e94-9d832f837d9e', 'N4', 'Vる／Vた／Nの＋とおりに', 'Theo như ~', 'とおりに = làm đúng theo, không sai khác', 'V(thể từ điển／thể た)／N + の + とおりに', 'Làm 1 việc đúng theo cách/lời chỉ dẫn đã cho', NULL, NULL, NULL, '{}', NULL, 40, 'Vる／Vた／Nの＋とおりに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a6f82883-97b2-4dc5-b4ad-8cc0f73fa1ff', 'N4', 'V1た／Nの＋あとで', 'Sau khi ~', 'あとで đặt sau thể た của động từ hoặc の của danh từ', 'V(thể た)／N + の + あとで', 'Diễn tả 1 hành động xảy ra sau 1 hành động/sự kiện khác', NULL, NULL, NULL, '{}', NULL, 40, 'V1た／Nの＋あとで', 'pdf', 'ok')
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c8423c9a-44a2-40be-8f74-4316fae629e4', NULL, 1, 'daily', '東京へ出張の予定です。', 'Tôi có kế hoạch đi công tác ở Tokyo.', '東京へ出張の＿＿＿。', '予定です', 'pdf');
