insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c8423c9a-44a2-40be-8f74-4316fae629e4', NULL, 3, 'daily', '会議は3時に始まる予定です。', 'Cuộc họp có kế hoạch bắt đầu lúc 3 giờ.', '会議は3時に＿＿＿。', '始まる予定です', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c4947afa-27a3-4969-9c15-b5d8b5c4ee7f', NULL, 1, 'daily', 'ひどくなったね。病院へ行ったほうがいいです。', 'Bệnh trở nặng hơn rồi. Bạn nên đi đến bệnh viện.', '病院へ＿＿＿。', '行ったほうがいいです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c4947afa-27a3-4969-9c15-b5d8b5c4ee7f', NULL, 2, 'daily', '風邪ですか。運動しないほうがいい。', 'Bạn bị cảm hả? Bạn không nên tập thể dục.', '風邪ですか。＿＿＿。', '運動しないほうがいい', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c4947afa-27a3-4969-9c15-b5d8b5c4ee7f', NULL, 3, 'daily', 'もっと野菜を食べたほうがいいですよ。', 'Bạn nên ăn nhiều rau hơn đấy.', 'もっと野菜を＿＿＿よ。', '食べたほうがいいです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4eb8d331-dca6-488c-b573-7574fc26ebec', NULL, 1, 'daily', '明日、雨が降るでしょう。', 'Có lẽ ngày mai sẽ mưa.', '明日、雨が＿＿＿。', '降るでしょう', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4eb8d331-dca6-488c-b573-7574fc26ebec', NULL, 2, 'daily', '彼はもうすぐ来るでしょう。', 'Chắc là anh ấy sắp đến rồi.', '彼はもうすぐ＿＿＿。', '来るでしょう', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4eb8d331-dca6-488c-b573-7574fc26ebec', NULL, 3, 'daily', '今日は忙しいでしょう。', 'Hôm nay chắc là bạn bận.', '今日は＿＿＿。', '忙しいでしょう', 'generated');
