insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4d58ed1b-49a1-470f-9aa0-2c3f3906e99e', NULL, 2, 'daily', '彼は今日休むかもしれません。', 'Có lẽ hôm nay anh ấy sẽ nghỉ.', '彼は今日＿＿＿。', '休むかもしれません', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('4d58ed1b-49a1-470f-9aa0-2c3f3906e99e', NULL, 3, 'daily', 'この話は本当かもしれません。', 'Câu chuyện này có lẽ là thật.', 'この話は＿＿＿。', '本当かもしれません', 'generated');
