insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ca85c642-3809-40a0-8f99-d5a31b061abc', NULL, 2, 'daily', 'ここに入るな。', 'Đừng vào đây.', 'ここに＿＿＿。', '入るな', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ca85c642-3809-40a0-8f99-d5a31b061abc', NULL, 3, 'daily', '心配するな。', 'Đừng lo lắng.', '＿＿＿。', '心配するな', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1f83aafa-6b81-40ec-9053-91cec31ec163', NULL, 1, 'daily', 'はやく食べなさい。', 'Ăn nhanh lên.', 'はやく＿＿＿。', '食べなさい', 'pdf');
