insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ad936b93-4969-47dc-bc57-0425dadfec8d', NULL, 1, 'daily', '「ありがとう」は“Cảm ơn”という意味です。', '“Arigatou” có nghĩa là “Cảm ơn”.', '「ありがとう」は“Cảm ơn”＿＿＿。', 'という意味です', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ad936b93-4969-47dc-bc57-0425dadfec8d', NULL, 2, 'daily', '「さようなら」は“Tạm biệt”という意味です。', '“Sayounara” có nghĩa là “Tạm biệt”.', '「さようなら」は“Tạm biệt”＿＿＿。', 'という意味です', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ad936b93-4969-47dc-bc57-0425dadfec8d', NULL, 3, 'daily', '「頑張って」は“Cố lên”という意味です。', '“Ganbatte” có nghĩa là “Cố lên”.', '「頑張って」は“Cố lên”＿＿＿。', 'という意味です', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('294898ce-a57f-4600-b6ec-6d1f27afb3ee', NULL, 1, 'daily', '田中さんが10時に本社に来てくれると言っていました。', 'Ông Tanaka đã nói rằng sẽ đến trụ sở chính lúc 10 giờ.', '田中さんが10時に本社に＿＿＿。', '来てくれると言っていました', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('294898ce-a57f-4600-b6ec-6d1f27afb3ee', NULL, 2, 'daily', '彼は明日休むと言いました。', 'Anh ấy đã nói rằng ngày mai sẽ nghỉ.', '彼は明日＿＿＿。', '休むと言いました', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('294898ce-a57f-4600-b6ec-6d1f27afb3ee', NULL, 3, 'daily', '先生は宿題が多いと言っていました。', 'Thầy/cô đã nói rằng bài tập rất nhiều.', '先生は宿題が＿＿＿。', '多いと言っていました', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fbd18589-8f92-4ae2-a26c-7a23573e1e55', NULL, 1, 'daily', 'ワンさんに「後で電話をください」と伝えていただけませんか。', 'Bạn có thể nói với Quang là “Gọi cho tôi sau” được không?', 'ワンさんに「後で電話をください」と＿＿＿。', '伝えていただけませんか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fbd18589-8f92-4ae2-a26c-7a23573e1e55', NULL, 2, 'daily', '田中さんに「会議は3時からです」と伝えていただけませんか。', 'Bạn có thể nói với anh Tanaka là “Cuộc họp bắt đầu từ 3 giờ” được không?', '田中さんに「会議は3時からです」と＿＿＿。', '伝えていただけませんか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('fbd18589-8f92-4ae2-a26c-7a23573e1e55', NULL, 3, 'daily', '部長に「明日休みます」と伝えていただけませんか。', 'Bạn có thể nói với trưởng phòng là “Ngày mai tôi nghỉ” được không?', '部長に「明日休みます」と＿＿＿。', '伝えていただけませんか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e99239c7-348f-4743-9e94-9d832f837d9e', NULL, 1, 'daily', '私が今から言うとおりに、書いてください。', 'Hãy viết theo những gì tôi sẽ nói bây giờ.', '私が今から言う＿＿＿、書いてください。', 'とおりに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e99239c7-348f-4743-9e94-9d832f837d9e', NULL, 2, 'daily', '説明書のとおりに、組み立ててください。', 'Xin hãy lắp ráp theo như sách hướng dẫn.', '説明書の＿＿＿、組み立ててください。', 'とおりに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e99239c7-348f-4743-9e94-9d832f837d9e', NULL, 3, 'daily', '先生が教えたとおりに、練習しました。', 'Tôi đã luyện tập theo như thầy/cô đã dạy.', '先生が教えた＿＿＿、練習しました。', 'とおりに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a6f82883-97b2-4dc5-b4ad-8cc0f73fa1ff', NULL, 1, 'daily', '新しいのを買ったあとで、なくした本がみつかりました。', 'Sau khi mua cuốn sách mới, tôi tìm thấy cuốn sách mà tôi đã mất.', '新しいのを買った＿＿＿、なくした本がみつかりました。', 'あとで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a6f82883-97b2-4dc5-b4ad-8cc0f73fa1ff', NULL, 2, 'daily', '食事のあとで、薬を飲んでください。', 'Xin hãy uống thuốc sau khi ăn.', '食事の＿＿＿、薬を飲んでください。', 'あとで', 'generated');
